class MeineQueue
{
    private Knoten? vorne, hinten;
    public int Count { get; private set; }

    public void Enqueue(int wert)
    {
        var neu = new Knoten(wert);
        if (hinten == null)
            vorne = hinten = neu;
        else
        {
            hinten.Next = neu;
            hinten = neu;
        }
        Count++;
    }

    public int Dequeue()
    {
        if (vorne == null)
            throw new InvalidOperationException(
                "Queue ist leer");
        int wert = vorne.Wert;
        vorne = vorne.Next;
        if (vorne == null) hinten = null;
        Count--;
        return wert;
    }
}

var bereit = new Queue<Prozess>();
bereit.Enqueue(new Prozess("A", 30));
bereit.Enqueue(new Prozess("B", 10));
bereit.Enqueue(new Prozess("C", 20));
int zeit = 0;

while (bereit.Count > 0)
{
    Prozess p = bereit.Dequeue();
    p.Rest -= 10; // Zeitscheibe 10 ms
    zeit += 10;
    if (p.Rest > 0)
        bereit.Enqueue(p); // hinten an
    else
        Console.WriteLine(
            $"{p.Name} fertig: {zeit} ms");
}
// Ausgabe:
// B fertig: 20 ms
// C fertig: 50 ms
// A fertig: 60 ms

class Prozess
{
    public string Name;
    public int Rest;
    public Prozess(string name, int rest)
    {
        Name = name;
        Rest = rest;
    }
}

